<?php
namespace App\Services;
use Carbon\CarbonImmutable as Date;
use Illuminate\Support\Facades\{DB,Crypt};
use Illuminate\Support\Str;
final class Waitlist {
 public static function data(object $row):array{return json_decode(Crypt::decryptString($row->payload),true,64,JSON_THROW_ON_ERROR);}
 public static function enqueue(int $provider,string $entry,string $kind):void {DB::table('deliveries')->insertOrIgnore(['provider_id'=>$provider,'dedup'=>hash('sha256',$kind.':'.$entry),'payload'=>Crypt::encryptString(json_encode(['kind'=>$kind,'entryId'=>$entry,'channel'=>'email'])),'status'=>'pending','available_at'=>now(),'attempts'=>0,'created_at'=>now(),'updated_at'=>now()]);}
 public static function join(array $v):void {
  $provider=app(Tenant::class)->id;$v['email']=Contact::email($v['email']);sort($v['services']);$dedup=hash_hmac('sha256',json_encode([$v['email'],$v['services'],$v['staff']??'any',$v['firstDate'],$v['lastDate'],$v['timeFrom'],$v['timeTo']]),config('app.key'));
  app(SalonStore::class)->mutate(function(&$s)use($v,$provider,$dedup){Subscriptions::guard($s,false);abort_unless(!empty($s['settings']['waitlistEnabled']),422,'A szolgáltatónál a várólista nincs bekapcsolva.');Blacklist::guard($s,['email'=>$v['email']]);$catalog=collect($s['services'])->filter(fn($x)=>empty($x['archived']));foreach($v['services'] as $id)abort_unless($catalog->contains('id',$id),422,'Válassz foglalható szolgáltatást.');$people=Settings::activeStaff($s);$eligible=array_filter($people,fn($p)=>empty($v['staff'])||$v['staff']==='any'||$v['staff']===$p['id']);$eligible=array_filter($eligible,fn($p)=>!$catalog->whereIn('id',$v['services'])->contains(fn($service)=>!in_array($p['id'],Settings::serviceStaff($s,$service),true)));abort_unless($eligible,422,'Nincs a szolgáltatásokat végző munkatárs.');
   if(DB::table('waitlist_entries')->where('provider_id',$provider)->where('dedup',$dedup)->whereIn('status',['pending','active','checking','queued'])->exists())return;abort_if(DB::table('waitlist_entries')->where('provider_id',$provider)->whereIn('status',['pending','active','checking','queued'])->count()>=2000,422,'A várólista most megtelt. Keresd közvetlenül a szolgáltatót.');$id=(string)Str::uuid();$token=bin2hex(random_bytes(32));DB::table('waitlist_entries')->insert(['id'=>$id,'provider_id'=>$provider,'dedup'=>$dedup,'token_hash'=>hash('sha256',$token),'payload'=>Crypt::encryptString(json_encode($v+['token'=>$token])),'status'=>'pending','first_date'=>$v['firstDate'],'last_date'=>$v['lastDate'],'created_at'=>now(),'updated_at'=>now()]);self::enqueue($provider,$id,'waitlist_verify');
  },false);
 }
 public static function slots(array $s,array $v,string $date):array {
  $probe=\Illuminate\Http\Request::create('/api/slots','GET',['date'=>$date,'services'=>implode(',',$v['services']),'staff'=>$v['staff']??'any','public'=>1]);$probe->setLaravelSession(new \Illuminate\Session\Store('waitlist',new \Illuminate\Session\ArraySessionHandler(120)));
  return array_values(array_filter(app(\App\Http\Controllers\SalonController::class)->slots($probe,$s),fn($slot)=>$slot['time']>=$v['timeFrom']&&$slot['time']<=$v['timeTo']));
 }
 public static function run(int $limit=10):array {
  DB::table('waitlist_entries')->where('last_date','<',now('Europe/Budapest')->toDateString())->whereIn('status',['pending','active','queued','unknown','checking'])->update(['status'=>'expired','updated_at'=>now()]);DB::table('waitlist_entries')->where('status','checking')->where('locked_at','<',now()->subMinutes(10))->update(['status'=>'active']);$counts=['checked'=>0,'queued'=>0];
  for($i=0;$i<min(20,$limit);$i++){$row=DB::transaction(function(){$row=DB::table('waitlist_entries')->where('status','active')->where(fn($q)=>$q->whereNull('checked_at')->orWhere('checked_at','<',now()->subMinutes(2)))->orderBy('checked_at')->lockForUpdate()->first();if($row)DB::table('waitlist_entries')->where('id',$row->id)->update(['status'=>'checking','locked_at'=>now(),'checked_at'=>now()]);return $row;});if(!$row)break;
   try{app(Tenant::class)->run((int)$row->provider_id,function()use($row,&$counts){$s=app(SalonStore::class)->read();if(empty($s['settings']['waitlistEnabled'])){DB::table('waitlist_entries')->where('id',$row->id)->where('status','checking')->update(['status'=>'active','updated_at'=>now()]);return;}Subscriptions::guard($s,false);$v=self::data($row);Blacklist::guard($s,['email'=>$v['email']]);$first=max(now('Europe/Budapest')->toDateString(),$row->first_date);$cursor=max($first,$row->cursor_date??$first);$slot=null;for($n=0;$n<7&&$cursor<=$row->last_date;$n++){$slots=self::slots($s,$v,$cursor);if($slots){$slot=$slots[0];break;}$cursor=Date::parse($cursor)->addDay()->toDateString();}$counts['checked']++;
    DB::transaction(function()use($row,$v,$cursor,$first,$slot,&$counts){$current=DB::table('waitlist_entries')->where('id',$row->id)->lockForUpdate()->first();if($current->status!=='checking')return;if($slot){DB::table('waitlist_entries')->where('id',$row->id)->update(['status'=>'queued','payload'=>Crypt::encryptString(json_encode(array_replace($v,['offer'=>$slot]))),'updated_at'=>now()]);self::enqueue((int)$row->provider_id,$row->id,'waitlist_available');$counts['queued']++;}else DB::table('waitlist_entries')->where('id',$row->id)->update(['status'=>'active','cursor_date'=>$cursor>$row->last_date?$first:$cursor,'updated_at'=>now()]);});
   });}catch(\Throwable $e){SystemIssues::capture($e,'waitlist',(int)$row->provider_id);DB::table('waitlist_entries')->where('id',$row->id)->where('status','checking')->update(['status'=>'active','updated_at'=>now()]);}
  }return $counts;
 }
 public static function deliver(string $id,string $kind):string {
  $row=DB::table('waitlist_entries')->where('provider_id',app(Tenant::class)->id)->find($id);if(!$row||$row->last_date<now('Europe/Budapest')->toDateString())return 'skipped';$v=self::data($row);$s=app(SalonStore::class)->read();if(empty($s['settings']['waitlistEnabled']))return 'blocked';$manage=rtrim(config('app.url'),'/').'/varolista/'.$v['token'];$verify=$kind==='waitlist_verify';if($verify&&$row->status!=='pending')return 'skipped';if(!$verify&&$row->status!=='queued')return 'skipped';
  if(!$verify){try{Subscriptions::guard($s,false);Blacklist::guard($s,['email'=>$v['email']]);$day=Date::parse($v['offer']['start'])->setTimezone('Europe/Budapest')->toDateString();$stillFree=collect(self::slots($s,$v,$day))->contains(fn($x)=>$x['start']===$v['offer']['start']&&$x['staff']===$v['offer']['staff']);}catch(\Throwable){$stillFree=false;}if(!$stillFree){DB::table('waitlist_entries')->where('id',$id)->update(['status'=>'active','cursor_date'=>null,'updated_at'=>now()]);DB::table('deliveries')->where('provider_id',$row->provider_id)->where('dedup',hash('sha256','waitlist_available:'.$id))->update(['dedup'=>hash('sha256','stale:'.$id.':'.Str::uuid())]);return 'skipped';}}
  $url=$verify?$manage:rtrim(config('app.url'),'/').'/foglalas?provider='.$row->provider_id.'&waitlist='.$v['token'];$details=$verify?'Erősítsd meg a várólistás jelentkezésedet a hivatkozáson. Csak egyszer értesítünk, ha a megadott szolgáltatásra megfelelő szabad időpontot találunk. Ez nem hírlevél-feliratkozás.':'Megfelelő szabad időpontot találtunk: '.Date::parse($v['offer']['start'])->setTimezone('Europe/Budapest')->format('Y.m.d. H:i').'. Az értesítés nem foglalás és nem tartja fenn a helyet; a szabad időpontot a foglalóoldalon tudod lefoglalni. Várólista kezelése: '.$manage;
  $status=SystemMail::send($v['email'],$kind,['business'=>$s['settings']['name'],'name'=>$v['name'],'details'=>$details,'manage_url'=>$url]);if($status==='sent'&&!$verify)DB::table('waitlist_entries')->where('id',$id)->where('status','queued')->update(['status'=>'notified','notified_at'=>now(),'updated_at'=>now()]);return $status;
 }
}
